import 'package:family_veda/models/member.dart';
import 'package:family_veda/providers/active_member_provider.dart';
import 'package:family_veda/providers/auth_provider.dart';
import 'package:family_veda/providers/core_providers.dart';
import 'package:family_veda/providers/family_dashboard_role_provider.dart';
import 'package:family_veda/providers/family_portal_provider.dart';
import 'package:family_veda/providers/members_provider.dart';
import 'package:family_veda/theme/app_theme.dart';
import 'package:family_veda/widgets/family/incoming_invitations_section.dart';
import 'package:family_veda/widgets/shared/async_state_views.dart';
import 'package:family_veda/widgets/shared/member_card.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:intl/intl.dart';

class MembersScreen extends ConsumerStatefulWidget {
  const MembersScreen({super.key});

  @override
  ConsumerState<MembersScreen> createState() => _MembersScreenState();
}

class _MembersScreenState extends ConsumerState<MembersScreen> {
  int _activeTab = 0; // 0: Members, 1: Join Requests, 2: Invitations, 3: Family Settings

  // Invitations form controllers
  final _inviteEmailController = TextEditingController();
  final _inviteRelationshipController = TextEditingController();
  FamilyInvitationIssued? _issuedToken;
  bool _isInviting = false;

  // Family settings controllers
  final _familyNameController = TextEditingController();
  bool _isSavingName = false;
  String? _selectedTransferMemberId;
  bool _isTransferring = false;

  @override
  void dispose() {
    _inviteEmailController.dispose();
    _inviteRelationshipController.dispose();
    _familyNameController.dispose();
    super.dispose();
  }

  void _showMessage(String message, {bool isError = false, bool isSuccess = false}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message),
        backgroundColor: isError
            ? AppColors.danger
            : isSuccess
                ? AppColors.success
                : const Color(0xFF1D61E0),
      ),
    );
  }

  Future<void> _handleAcceptRequest(String familyId, String requestId, String name) async {
    try {
      await ref.read(familyPortalApiProvider).acceptJoinRequest(requestId);
      ref.invalidate(pendingJoinRequestsProvider(familyId));
      ref.invalidate(membersProvider);
      ref.invalidate(familyDashboardProvider);
      _showMessage('$name joined the family. Their health data stays private by default.', isSuccess: true);
    } catch (_) {
      _showMessage('The request could not be accepted. Try again.', isError: true);
    }
  }

  Future<void> _handleDeclineRequest(String familyId, String requestId, String name) async {
    try {
      await ref.read(familyPortalApiProvider).declineJoinRequest(requestId);
      ref.invalidate(pendingJoinRequestsProvider(familyId));
      ref.invalidate(familyDashboardProvider);
      _showMessage('Request from $name declined.');
    } catch (_) {
      _showMessage('The request could not be declined. Try again.', isError: true);
    }
  }

  Future<void> _handleCreateInvitation(String familyId) async {
    final email = _inviteEmailController.text.trim();
    if (email.isEmpty || !email.contains('@')) {
      _showMessage('Please enter a valid adult account email.', isError: true);
      return;
    }
    setState(() => _isInviting = true);
    try {
      final issued = await ref.read(familyPortalApiProvider).createInvitation(
            familyId,
            email: email,
            relationshipType: _inviteRelationshipController.text.trim(),
          );
      setState(() {
        _issuedToken = issued;
        _inviteEmailController.clear();
        _inviteRelationshipController.clear();
      });
      ref.invalidate(familySentInvitationsProvider(familyId));
      if (mounted) {
        showDialog<void>(
          context: context,
          builder: (ctx) => AlertDialog(
            title: const Row(
              children: [
                Icon(Icons.check_circle_rounded, color: Color(0xFF16A34A)),
                SizedBox(width: 8),
                Text('Invitation Created', style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
              ],
            ),
            content: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  'Share this one-time token privately with the invited adult:',
                  style: TextStyle(fontSize: 13),
                ),
                const SizedBox(height: 12),
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
                  decoration: BoxDecoration(
                    color: const Color(0xFFEFF6FF),
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(color: const Color(0xFF93C5FD)),
                  ),
                  child: Row(
                    children: [
                      Expanded(
                        child: SelectableText(
                          issued.token,
                          style: const TextStyle(
                            fontSize: 15,
                            fontWeight: FontWeight.w800,
                            letterSpacing: 0.5,
                            color: Color(0xFF1E3A8A),
                          ),
                        ),
                      ),
                      IconButton(
                        icon: const Icon(Icons.copy_rounded, color: Color(0xFF2563EB)),
                        onPressed: () {
                          Clipboard.setData(ClipboardData(text: issued.token));
                          _showMessage('Token copied to clipboard.', isSuccess: true);
                        },
                      ),
                    ],
                  ),
                ),
                if (issued.expiresAt != null) ...[
                  const SizedBox(height: 8),
                  Text(
                    'Valid until ${DateFormat('MMM d, yyyy · h:mm a').format(issued.expiresAt!)}',
                    style: const TextStyle(fontSize: 11.5, color: Color(0xFF64748B)),
                  ),
                ],
              ],
            ),
            actions: [
              ElevatedButton(
                onPressed: () => Navigator.of(ctx).pop(),
                style: ElevatedButton.styleFrom(backgroundColor: const Color(0xFF1D61E0)),
                child: const Text('Done', style: TextStyle(color: Colors.white)),
              ),
            ],
          ),
        );
      }
      _showMessage('Invitation created. Share the token privately.', isSuccess: true);
    } catch (_) {
      _showMessage('The invitation could not be created. Try again.', isError: true);
    } finally {
      if (mounted) setState(() => _isInviting = false);
    }
  }

  Future<void> _handleCancelInvitation(String familyId, String invitationId) async {
    try {
      await ref.read(familyPortalApiProvider).cancelInvitation(familyId, invitationId);
      ref.invalidate(familySentInvitationsProvider(familyId));
      _showMessage('Invitation cancelled.');
    } catch (_) {
      _showMessage('The invitation could not be cancelled. Try again.', isError: true);
    }
  }

  Future<void> _handleResendInvitation(String familyId, String invitationId, String? emailMasked) async {
    final emailController = TextEditingController();
    final result = await showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Resend Invitation'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('Re-enter the email address for ${emailMasked ?? 'this invitation'}:'),
            const SizedBox(height: 10),
            TextField(
              controller: emailController,
              keyboardType: TextInputType.emailAddress,
              decoration: const InputDecoration(
                labelText: 'Account email',
                border: OutlineInputBorder(),
              ),
            ),
          ],
        ),
        actions: [
          TextButton(onPressed: () => Navigator.of(ctx).pop(), child: const Text('Cancel')),
          ElevatedButton(
            onPressed: () => Navigator.of(ctx).pop(emailController.text.trim()),
            child: const Text('Issue New Token'),
          ),
        ],
      ),
    );

    if (result == null || result.isEmpty || !mounted) return;

    try {
      final issued = await ref.read(familyPortalApiProvider).resendInvitation(
            familyId,
            invitationId,
            result,
          );
      setState(() => _issuedToken = issued);
      ref.invalidate(familySentInvitationsProvider(familyId));
      _showMessage('New invitation token issued. The previous token no longer works.', isSuccess: true);
    } catch (_) {
      _showMessage('The invitation could not be resent. Try again.', isError: true);
    }
  }

  Future<void> _handleSaveFamilyName(String familyId) async {
    final name = _familyNameController.text.trim();
    if (name.length < 2) {
      _showMessage('The family name needs at least 2 characters.', isError: true);
      return;
    }
    setState(() => _isSavingName = true);
    try {
      await ref.read(familyPortalApiProvider).renameFamily(familyId, name);
      ref.invalidate(familyDashboardProvider);
      _showMessage('Family name saved.', isSuccess: true);
    } catch (_) {
      _showMessage('The family name could not be saved.', isError: true);
    } finally {
      if (mounted) setState(() => _isSavingName = false);
    }
  }

  Future<void> _handleTransferHead(String familyId) async {
    final toMemberId = _selectedTransferMemberId;
    if (toMemberId == null) {
      _showMessage('Please select an adult member to transfer the Family Head role to.', isError: true);
      return;
    }
    setState(() => _isTransferring = true);
    try {
      await ref.read(familyPortalApiProvider).proposeHeadTransfer(familyId, toMemberId);
      ref.invalidate(familyDashboardProvider);
      _showMessage('Family Head transfer proposed. The member has been notified.', isSuccess: true);
    } catch (_) {
      _showMessage('Could not propose head transfer. Try again.', isError: true);
    } finally {
      if (mounted) setState(() => _isTransferring = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final membersAsync = ref.watch(membersProvider);
    final dashboardAsync = ref.watch(familyDashboardProvider);
    final activeId = ref.watch(activeMemberProvider);
    final isHead = ref.watch(isFamilyHeadProvider).valueOrNull ?? false;
    final isDark = Theme.of(context).brightness == Brightness.dark;

    final dashboard = dashboardAsync.valueOrNull;
    final familyId = dashboard?.familyId ?? '';
    final familyName = dashboard?.familyName ?? 'My Family';
    final familyCode = dashboard?.familyCode;
    final pendingRequestsCount = dashboard?.pendingJoinRequests ?? 0;

    if (_familyNameController.text.isEmpty && dashboard?.familyName != null) {
      _familyNameController.text = dashboard!.familyName!;
    }

    return Scaffold(
      backgroundColor: Colors.transparent,
      body: SafeArea(
        child: RefreshIndicator(
          onRefresh: () async {
            ref.invalidate(membersProvider);
            ref.invalidate(familyDashboardProvider);
            if (familyId.isNotEmpty) {
              ref.invalidate(pendingJoinRequestsProvider(familyId));
              ref.invalidate(familySentInvitationsProvider(familyId));
            }
          },
          child: ListView(
            physics: const AlwaysScrollableScrollPhysics(parent: BouncingScrollPhysics()),
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
            children: [
              // 1. Web-Aligned Royal Blue Hero Banner
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(20),
                decoration: BoxDecoration(
                  gradient: const LinearGradient(
                    colors: [Color(0xFF0F52BA), Color(0xFF1976D2), Color(0xFF0288D1)],
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                  ),
                  borderRadius: BorderRadius.circular(18),
                  boxShadow: [
                    BoxShadow(
                      color: const Color(0xFF0F52BA).withValues(alpha: 0.35),
                      blurRadius: 16,
                      offset: const Offset(0, 6),
                    ),
                  ],
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Container(
                          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                          decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.2),
                            borderRadius: BorderRadius.circular(6),
                          ),
                          child: const Text(
                            'MEMBERSHIP',
                            style: TextStyle(
                              fontSize: 10,
                              fontWeight: FontWeight.w800,
                              letterSpacing: 1.1,
                              color: Colors.white,
                            ),
                          ),
                        ),
                        if (familyCode != null && familyCode.isNotEmpty)
                          InkWell(
                            onTap: () {
                              Clipboard.setData(ClipboardData(text: familyCode));
                              _showMessage('Family Code $familyCode copied to clipboard.', isSuccess: true);
                            },
                            borderRadius: BorderRadius.circular(6),
                            child: Container(
                              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                              decoration: BoxDecoration(
                                color: Colors.white.withValues(alpha: 0.25),
                                borderRadius: BorderRadius.circular(6),
                              ),
                              child: Row(
                                mainAxisSize: MainAxisSize.min,
                                children: [
                                  const Icon(Icons.copy_rounded, size: 12, color: Colors.white),
                                  const SizedBox(width: 4),
                                  Text(
                                    familyCode,
                                    style: const TextStyle(
                                      fontSize: 11,
                                      fontWeight: FontWeight.w800,
                                      letterSpacing: 0.8,
                                      color: Colors.white,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ),
                      ],
                    ),
                    const SizedBox(height: 8),
                    Text(
                      familyName,
                      style: const TextStyle(
                        fontSize: 22,
                        fontWeight: FontWeight.w800,
                        color: Colors.white,
                        letterSpacing: -0.3,
                      ),
                    ),
                    const SizedBox(height: 6),
                    Text(
                      'Manage members, join requests, invitations and family settings. Adult health data stays private unless shared.',
                      style: TextStyle(
                        fontSize: 13,
                        color: Colors.white.withValues(alpha: 0.9),
                        height: 1.35,
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 16),

              // 2. The 4 Sub-Tabs Navigation Bar (Members | Join Requests | Invitations | Family Settings)
              _buildSubTabBar(
                isDark: isDark,
                pendingRequestsCount: pendingRequestsCount,
              ),
              const SizedBox(height: 16),

              // 3. Tab Content Switcher
              if (_activeTab == 0)
                _buildMembersTab(
                  membersAsync: membersAsync,
                  activeId: activeId,
                  isDark: isDark,
                )
              else if (_activeTab == 1)
                _buildJoinRequestsTab(
                  familyId: familyId,
                  isDark: isDark,
                )
              else if (_activeTab == 2)
                _buildInvitationsTab(
                  familyId: familyId,
                  isDark: isDark,
                )
              else
                _buildFamilySettingsTab(
                  familyId: familyId,
                  familyCode: familyCode,
                  membersAsync: membersAsync,
                  isHead: isHead,
                  isDark: isDark,
                ),

              const SizedBox(height: 40),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildSubTabBar({
    required bool isDark,
    required int pendingRequestsCount,
  }) {
    final tabs = [
      {'title': 'Members', 'count': 0},
      {'title': 'Join Requests', 'count': pendingRequestsCount},
      {'title': 'Invitations', 'count': 0},
      {'title': 'Family Settings', 'count': 0},
    ];

    return Container(
      decoration: BoxDecoration(
        color: isDark ? const Color(0xFF1E293B) : Colors.white,
        borderRadius: BorderRadius.circular(14),
        border: Border.all(
          color: isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0),
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: isDark ? 0.2 : 0.03),
            blurRadius: 8,
            offset: const Offset(0, 3),
          ),
        ],
      ),
      child: SingleChildScrollView(
        scrollDirection: Axis.horizontal,
        physics: const BouncingScrollPhysics(),
        child: Row(
          children: List.generate(tabs.length, (index) {
            final tab = tabs[index];
            final title = tab['title'] as String;
            final count = tab['count'] as int;
            final isSelected = _activeTab == index;

            return InkWell(
              onTap: () => setState(() => _activeTab = index),
              borderRadius: BorderRadius.circular(12),
              child: Container(
                padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                decoration: BoxDecoration(
                  border: Border(
                    bottom: BorderSide(
                      color: isSelected ? const Color(0xFF1D61E0) : Colors.transparent,
                      width: 2.5,
                    ),
                  ),
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      title,
                      style: TextStyle(
                        fontSize: 13.5,
                        fontWeight: isSelected ? FontWeight.w800 : FontWeight.w600,
                        color: isSelected
                            ? (isDark ? const Color(0xFF93C5FD) : const Color(0xFF1D61E0))
                            : (isDark ? AppColors.mutedDark : const Color(0xFF64748B)),
                      ),
                    ),
                    if (count > 0) ...[
                      const SizedBox(width: 6),
                      Container(
                        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                        decoration: BoxDecoration(
                          color: const Color(0xFFEF4444),
                          borderRadius: BorderRadius.circular(10),
                        ),
                        child: Text(
                          '$count',
                          style: const TextStyle(
                            fontSize: 10,
                            fontWeight: FontWeight.w800,
                            color: Colors.white,
                          ),
                        ),
                      ),
                    ],
                  ],
                ),
              ),
            );
          }),
        ),
      ),
    );
  }

  // TAB 1: MEMBERS
  Widget _buildMembersTab({
    required AsyncValue<List<Member>> membersAsync,
    required String? activeId,
    required bool isDark,
  }) {
    final dashboard = ref.watch(familyDashboardProvider).valueOrNull;
    final fallbackMembers = (dashboard?.members ?? const [])
        .map((dm) => Member(
              id: dm.id,
              displayName: dm.displayName,
              relationshipLabel: dm.role,
            ))
        .toList();

    return membersAsync.when(
      loading: () => fallbackMembers.isNotEmpty
          ? _renderRoster(fallbackMembers, activeId, isDark)
          : const LoadingStateView(label: 'Loading members'),
      error: (_, _) => fallbackMembers.isNotEmpty
          ? _renderRoster(fallbackMembers, activeId, isDark)
          : ErrorRetryView(
              onRetry: () => ref.invalidate(membersProvider),
            ),
      data: (items) {
        final displayItems = items.isNotEmpty ? items : fallbackMembers;
        if (displayItems.isEmpty) {
          return Container(
            padding: const EdgeInsets.all(24),
            decoration: BoxDecoration(
              color: isDark ? AppColors.surfaceDark : AppColors.surface,
              borderRadius: BorderRadius.circular(16),
              border: Border.all(
                color: isDark ? AppColors.borderDark : AppColors.border,
              ),
            ),
            child: const EmptyStateView(
              title: 'No family members yet',
              message: 'Add a member from family setup or join an existing family.',
            ),
          );
        }

        return Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(
                  'ROSTER (${items.length})',
                  style: TextStyle(
                    fontSize: 11.5,
                    fontWeight: FontWeight.w800,
                    letterSpacing: 0.8,
                    color: isDark ? AppColors.mutedDark : const Color(0xFF64748B),
                  ),
                ),
                Text(
                  'Tap to switch active member',
                  style: TextStyle(
                    fontSize: 11.5,
                    color: isDark ? AppColors.mutedDark : const Color(0xFF64748B),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 10),
            ...items.map(
              (member) => Padding(
                padding: const EdgeInsets.only(bottom: 10),
                child: MemberCard(
                  member: member,
                  isActive: member.id == activeId,
                  onSelected: () async {
                    final userId = ref.read(authProvider).userId;
                    if (userId == null) return;
                    ref.read(activeMemberProvider.notifier).state = member.id;
                    try {
                      await ref
                          .read(memberPreferenceStoreProvider)
                          .writeActiveMemberId(
                            userId: userId,
                            memberId: member.id,
                          );
                    } on Object {}
                  },
                ),
              ),
            ),
          ],
        );
      },
    );
  }

  // TAB 2: JOIN REQUESTS
  Widget _buildJoinRequestsTab({
    required String familyId,
    required bool isDark,
  }) {
    if (familyId.isEmpty) {
      return const EmptyStateView(
        title: 'No family profile',
        message: 'Join or create a family first.',
      );
    }

    final requestsAsync = ref.watch(pendingJoinRequestsProvider(familyId));

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const IncomingInvitationsSection(),
        const SizedBox(height: 12),
        Container(
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            color: isDark ? const Color(0xFF1E293B) : Colors.white,
            borderRadius: BorderRadius.circular(16),
            border: Border.all(
              color: isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0),
            ),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'Pending join requests',
                style: TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.w700,
                  color: isDark ? Colors.white : const Color(0xFF0F172A),
                ),
              ),
              const SizedBox(height: 4),
              Text(
                'Knowing the Family Code does not grant access. Unanswered requests expire after 14 days.',
                style: TextStyle(
                  fontSize: 12,
                  color: isDark ? AppColors.mutedDark : const Color(0xFF64748B),
                ),
              ),
              const SizedBox(height: 14),
              requestsAsync.when(
                loading: () => const Center(child: Padding(padding: EdgeInsets.all(16), child: CircularProgressIndicator())),
                error: (_, _) => ErrorRetryView(
                  onRetry: () => ref.invalidate(pendingJoinRequestsProvider(familyId)),
                ),
                data: (items) {
                  if (items.isEmpty) {
                    return const EmptyStateView(
                      title: 'No pending requests',
                      message: 'Nobody is waiting to join your family right now.',
                    );
                  }

                  return ListView.separated(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: items.length,
                    separatorBuilder: (_, _) => const Divider(height: 20),
                    itemBuilder: (context, index) {
                      final req = items[index];
                      return Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Row(
                            mainAxisAlignment: MainAxisAlignment.spaceBetween,
                            children: [
                              Text(
                                req.requesterDisplayName ?? 'Family Member',
                                style: const TextStyle(fontWeight: FontWeight.w700, fontSize: 14.5),
                              ),
                                Container(
                                  padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                                  decoration: BoxDecoration(
                                    color: const Color(0xFFEFF6FF),
                                    borderRadius: BorderRadius.circular(4),
                                  ),
                                  child: Text(
                                    req.relationshipType,
                                    style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w700, color: Color(0xFF1D4ED8)),
                                  ),
                                ),
                            ],
                          ),
                          if (req.requesterEmailMasked != null)
                            Text(
                              req.requesterEmailMasked!,
                              style: TextStyle(fontSize: 12, color: isDark ? AppColors.mutedDark : AppColors.muted),
                            ),
                          if (req.message != null && req.message!.isNotEmpty) ...[
                            const SizedBox(height: 4),
                            Text(
                              '"${req.message}"',
                              style: const TextStyle(fontSize: 12.5, fontStyle: FontStyle.italic),
                            ),
                          ],
                          const SizedBox(height: 10),
                          Row(
                            mainAxisAlignment: MainAxisAlignment.end,
                            children: [
                              OutlinedButton(
                                onPressed: () => _handleDeclineRequest(familyId, req.id, req.requesterDisplayName ?? 'Member'),
                                style: OutlinedButton.styleFrom(
                                  foregroundColor: AppColors.danger,
                                  side: const BorderSide(color: AppColors.danger),
                                  padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 6),
                                ),
                                child: const Text('Decline'),
                              ),
                              const SizedBox(width: 8),
                              ElevatedButton(
                                onPressed: () => _handleAcceptRequest(familyId, req.id, req.requesterDisplayName ?? 'Member'),
                                style: ElevatedButton.styleFrom(
                                  backgroundColor: const Color(0xFF1D61E0),
                                  foregroundColor: Colors.white,
                                  padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 6),
                                ),
                                child: const Text('Accept'),
                              ),
                            ],
                          ),
                        ],
                      );
                    },
                  );
                },
              ),
            ],
          ),
        ),
      ],
    );
  }

  // TAB 3: INVITATIONS
  Widget _buildInvitationsTab({
    required String familyId,
    required bool isDark,
  }) {
    if (familyId.isEmpty) {
      return const EmptyStateView(
        title: 'No family profile',
        message: 'Join or create a family first.',
      );
    }

    final sentAsync = ref.watch(familySentInvitationsProvider(familyId));

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // 1. Invite Adult Form
        Container(
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            color: isDark ? const Color(0xFF1E293B) : Colors.white,
            borderRadius: BorderRadius.circular(16),
            border: Border.all(
              color: isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0),
            ),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'Invite adult',
                style: TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.w700,
                  color: isDark ? Colors.white : const Color(0xFF0F172A),
                ),
              ),
              const SizedBox(height: 4),
              Text(
                'The token works once, only for the account with this email, for 48 hours.',
                style: TextStyle(
                  fontSize: 12,
                  color: isDark ? AppColors.mutedDark : const Color(0xFF64748B),
                ),
              ),
              const SizedBox(height: 14),
              TextField(
                controller: _inviteEmailController,
                keyboardType: TextInputType.emailAddress,
                decoration: const InputDecoration(
                  labelText: 'Adult account email',
                  hintText: 'adult@example.invalid',
                  border: OutlineInputBorder(),
                  prefixIcon: Icon(Icons.email_outlined, size: 20),
                ),
              ),
              const SizedBox(height: 10),
              TextField(
                controller: _inviteRelationshipController,
                decoration: const InputDecoration(
                  labelText: 'Relationship (optional)',
                  hintText: 'e.g. spouse, son',
                  border: OutlineInputBorder(),
                  prefixIcon: Icon(Icons.people_outline, size: 20),
                ),
              ),
              const SizedBox(height: 12),
              SizedBox(
                width: double.infinity,
                child: ElevatedButton(
                  onPressed: _isInviting ? null : () => _handleCreateInvitation(familyId),
                  style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF1D61E0),
                    foregroundColor: Colors.white,
                    padding: const EdgeInsets.symmetric(vertical: 12),
                  ),
                  child: _isInviting
                      ? const SizedBox(width: 20, height: 20, child: CircularProgressIndicator(color: Colors.white, strokeWidth: 2))
                      : const Text('Create invitation', style: TextStyle(fontWeight: FontWeight.w700)),
                ),
              ),
              if (_issuedToken != null) ...[
                const SizedBox(height: 14),
                Container(
                  padding: const EdgeInsets.all(12),
                  decoration: BoxDecoration(
                    color: const Color(0xFFEFF6FF),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(color: const Color(0xFFBFDBFE)),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text(
                        'One-time invitation token (shown once):',
                        style: TextStyle(fontSize: 12, fontWeight: FontWeight.w700, color: Color(0xFF1D4ED8)),
                      ),
                      const SizedBox(height: 6),
                      Row(
                        children: [
                          Expanded(
                            child: SelectableText(
                              _issuedToken!.token,
                              style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 13, letterSpacing: 0.5),
                            ),
                          ),
                          IconButton(
                            icon: const Icon(Icons.copy, size: 18, color: Color(0xFF1D4ED8)),
                            onPressed: () {
                              Clipboard.setData(ClipboardData(text: _issuedToken!.token));
                              _showMessage('Token copied to clipboard.', isSuccess: true);
                            },
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
              ],
            ],
          ),
        ),
        const SizedBox(height: 16),

        // 2. Sent Invitations List
        Container(
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            color: isDark ? const Color(0xFF1E293B) : Colors.white,
            borderRadius: BorderRadius.circular(16),
            border: Border.all(
              color: isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0),
            ),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'Sent invitations',
                style: TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.w700,
                  color: isDark ? Colors.white : const Color(0xFF0F172A),
                ),
              ),
              const SizedBox(height: 12),
              sentAsync.when(
                loading: () => const Center(child: Padding(padding: EdgeInsets.all(16), child: CircularProgressIndicator())),
                error: (_, _) => ErrorRetryView(
                  onRetry: () => ref.invalidate(familySentInvitationsProvider(familyId)),
                ),
                data: (items) {
                  if (items.isEmpty) {
                    return const EmptyStateView(
                      title: 'No invitations yet',
                      message: 'Invitations you create will appear here.',
                    );
                  }

                  return ListView.separated(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: items.length,
                    separatorBuilder: (_, _) => const Divider(height: 20),
                    itemBuilder: (context, index) {
                      final item = items[index];
                      final isPending = item.status == 'Pending';
                      final isExpired = item.status == 'Expired';

                      return Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Row(
                            mainAxisAlignment: MainAxisAlignment.spaceBetween,
                            children: [
                              Text(
                                item.emailMasked ?? 'Adult (email hidden)',
                                style: const TextStyle(fontWeight: FontWeight.w700, fontSize: 13.5),
                              ),
                              Container(
                                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                                decoration: BoxDecoration(
                                  color: isPending
                                      ? const Color(0xFFFEF3C7)
                                      : item.status == 'Accepted'
                                          ? const Color(0xFFDCFCE7)
                                          : const Color(0xFFF1F5F9),
                                  borderRadius: BorderRadius.circular(4),
                                ),
                                child: Text(
                                  item.status,
                                  style: TextStyle(
                                    fontSize: 10.5,
                                    fontWeight: FontWeight.w800,
                                    color: isPending
                                        ? const Color(0xFFB45309)
                                        : item.status == 'Accepted'
                                            ? const Color(0xFF166534)
                                            : const Color(0xFF64748B),
                                  ),
                                ),
                              ),
                            ],
                          ),
                          if (item.relationshipType != null)
                            Text(
                              'Relationship: ${item.relationshipType}',
                              style: TextStyle(fontSize: 12, color: isDark ? AppColors.mutedDark : AppColors.muted),
                            ),
                          if (item.expiresAt != null)
                            Text(
                              'Expires: ${DateFormat('MMM d, yyyy · h:mm a').format(item.expiresAt!)}',
                              style: TextStyle(fontSize: 11.5, color: isDark ? AppColors.mutedDark : AppColors.muted),
                            ),
                          if (isPending || isExpired) ...[
                            const SizedBox(height: 8),
                            Row(
                              mainAxisAlignment: MainAxisAlignment.end,
                              children: [
                                OutlinedButton(
                                  onPressed: () => _handleResendInvitation(familyId, item.id, item.emailMasked),
                                  style: OutlinedButton.styleFrom(
                                    padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
                                  ),
                                  child: const Text('Resend', style: TextStyle(fontSize: 12)),
                                ),
                                if (isPending) ...[
                                  const SizedBox(width: 8),
                                  OutlinedButton(
                                    onPressed: () => _handleCancelInvitation(familyId, item.id),
                                    style: OutlinedButton.styleFrom(
                                      foregroundColor: AppColors.danger,
                                      side: const BorderSide(color: AppColors.danger),
                                      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
                                    ),
                                    child: const Text('Cancel', style: TextStyle(fontSize: 12)),
                                  ),
                                ],
                              ],
                            ),
                          ],
                        ],
                      );
                    },
                  );
                },
              ),
            ],
          ),
        ),
      ],
    );
  }

  // TAB 4: FAMILY SETTINGS
  Widget _buildFamilySettingsTab({
    required String familyId,
    required String? familyCode,
    required AsyncValue<List<Member>> membersAsync,
    required bool isHead,
    required bool isDark,
  }) {
    if (familyId.isEmpty) {
      return const EmptyStateView(
        title: 'No family profile',
        message: 'Join or create a family first.',
      );
    }

    final members = membersAsync.valueOrNull ?? [];
    final eligibleAdults = members.where((m) => m.relationshipLabel.toLowerCase() != 'head').toList();

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // 1. Rename & Family Code Card
        Container(
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            color: isDark ? const Color(0xFF1E293B) : Colors.white,
            borderRadius: BorderRadius.circular(16),
            border: Border.all(
              color: isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0),
            ),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'Family Settings',
                style: TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.w700,
                  color: isDark ? Colors.white : const Color(0xFF0F172A),
                ),
              ),
              const SizedBox(height: 14),
              TextField(
                controller: _familyNameController,
                decoration: const InputDecoration(
                  labelText: 'Family name',
                  border: OutlineInputBorder(),
                  prefixIcon: Icon(Icons.home_outlined, size: 20),
                ),
              ),
              const SizedBox(height: 10),
              SizedBox(
                width: double.infinity,
                child: ElevatedButton(
                  onPressed: _isSavingName ? null : () => _handleSaveFamilyName(familyId),
                  style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF1D61E0),
                    foregroundColor: Colors.white,
                    padding: const EdgeInsets.symmetric(vertical: 12),
                  ),
                  child: _isSavingName
                      ? const SizedBox(width: 20, height: 20, child: CircularProgressIndicator(color: Colors.white, strokeWidth: 2))
                      : const Text('Save name', style: TextStyle(fontWeight: FontWeight.w700)),
                ),
              ),
              const SizedBox(height: 18),
              const Divider(),
              const SizedBox(height: 12),
              Text(
                'Family Code',
                style: TextStyle(
                  fontSize: 14,
                  fontWeight: FontWeight.w700,
                  color: isDark ? Colors.white : const Color(0xFF0F172A),
                ),
              ),
              const SizedBox(height: 6),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
                decoration: BoxDecoration(
                  color: isDark ? const Color(0xFF0F172A) : const Color(0xFFF8FAFC),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(color: isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0)),
                ),
                child: Row(
                  children: [
                    Expanded(
                      child: Text(
                        familyCode ?? 'Not assigned',
                        style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 14, letterSpacing: 1),
                      ),
                    ),
                    ElevatedButton.icon(
                      onPressed: familyCode == null
                          ? null
                          : () {
                              Clipboard.setData(ClipboardData(text: familyCode));
                              _showMessage('Family Code copied.', isSuccess: true);
                            },
                      icon: const Icon(Icons.copy, size: 14),
                      label: const Text('Copy code'),
                      style: ElevatedButton.styleFrom(
                        backgroundColor: const Color(0xFF1D61E0),
                        foregroundColor: Colors.white,
                        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 6),
              Text(
                'Share the code with an adult who should request to join. You still accept or decline every request.',
                style: TextStyle(fontSize: 12, color: isDark ? AppColors.mutedDark : const Color(0xFF64748B)),
              ),
            ],
          ),
        ),
        const SizedBox(height: 16),

        // 2. Transfer Family Head Role
        if (isHead)
          Container(
            padding: const EdgeInsets.all(16),
            decoration: BoxDecoration(
              color: isDark ? const Color(0xFF1E293B) : Colors.white,
              borderRadius: BorderRadius.circular(16),
              border: Border.all(
                color: isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0),
              ),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'Transfer Family Head role',
                  style: TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.w700,
                    color: isDark ? Colors.white : const Color(0xFF0F172A),
                  ),
                ),
                const SizedBox(height: 6),
                Text(
                  'Choose an adult family member to take over as Family Head. They must accept before the role changes.',
                  style: TextStyle(fontSize: 12, color: isDark ? AppColors.mutedDark : const Color(0xFF64748B)),
                ),
                const SizedBox(height: 14),
                if (eligibleAdults.isEmpty)
                  Text(
                    'No other adult members in the family yet.',
                    style: TextStyle(fontSize: 13, color: isDark ? AppColors.mutedDark : AppColors.muted, fontStyle: FontStyle.italic),
                  )
                else ...[
                  DropdownButtonFormField<String>(
                    // ignore: deprecated_member_use
                    value: _selectedTransferMemberId,
                    decoration: const InputDecoration(
                      labelText: 'Select new Family Head',
                      border: OutlineInputBorder(),
                    ),
                    items: eligibleAdults
                        .map((m) => DropdownMenuItem(value: m.id, child: Text(m.displayName)))
                        .toList(),
                    onChanged: (val) => setState(() => _selectedTransferMemberId = val),
                  ),
                  const SizedBox(height: 12),
                  SizedBox(
                    width: double.infinity,
                    child: OutlinedButton(
                      onPressed: _isTransferring ? null : () => _handleTransferHead(familyId),
                      style: OutlinedButton.styleFrom(
                        foregroundColor: const Color(0xFF1D61E0),
                        padding: const EdgeInsets.symmetric(vertical: 12),
                      ),
                      child: _isTransferring
                          ? const SizedBox(width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2))
                          : const Text('Propose Head Transfer', style: TextStyle(fontWeight: FontWeight.w700)),
                    ),
                  ),
                ],
              ],
            ),
          ),
      ],
    );
  }
}
